import * as t from 'node:assert/strict';
import { describe, it } from 'vitest';
import { parseSource } from '../../../src/parser';
import { fail, pass } from '../../test-utils';

describe('Next - Explicit Resource Management (using)', () => {
  pass('Next - using declarations (pass)', [
    // 'using' in module top-level
    { code: 'using foo = null', options: { sourceType: 'module', next: true } },
    { code: 'using a = 1, b = 2;', options: { sourceType: 'module', next: true } },
    // 'using' in non-global scopes of a script
    { code: '{ using foo = null; }', options: { next: true } },
    { code: 'function f() { using foo = null; }', options: { next: true } },
    { code: 'async function f() { using foo = null; }', options: { next: true } },
    { code: 'function* g() { using foo = null; }', options: { next: true } },
    { code: '() => { using foo = null; }', options: { next: true } },
    { code: 'class C { static { using foo = null; } }', options: { next: true } },
    { code: 'switch (x) { case 1: using foo = null; }', options: { next: true } },
    { code: 'try { using foo = null; } catch {}', options: { next: true } },
    { code: '{ using foo = null; }', options: { next: true, lexical: true } },
    // 'await using' in async contexts and module top-level
    { code: 'await using foo = null', options: { sourceType: 'module', next: true } },
    { code: '{ await using foo = null; }', options: { sourceType: 'module', next: true } },
    { code: 'async function f() { await using foo = null; }', options: { next: true } },
    { code: 'async function f() { await using a = 1, b = 2; }', options: { next: true } },
    { code: 'async () => { await using foo = null; }', options: { next: true } },
    { code: 'async function* g() { await using foo = null; }', options: { next: true } },
    { code: 'class C { static { await using foo = null; } }', options: { next: true } },
    { code: 'class C { static { await using foo = null; } }', options: { sourceType: 'module', next: true } },
    // export declarations
    { code: 'export using foo = null', options: { sourceType: 'module', next: true } },
    { code: 'export await using foo = null', options: { sourceType: 'module', next: true } },
    // for statement heads
    { code: 'for (using foo of bar) {}', options: { next: true } },
    { code: 'for (using foo of bar) {}', options: { sourceType: 'module', next: true } },
    { code: 'for (using foo = bar;;) {}', options: { next: true } },
    { code: 'for (using foo = bar, baz = qux;;) {}', options: { next: true } },
    { code: 'async function f() { for (await using foo of bar) {} }', options: { next: true } },
    { code: 'for (await using foo of bar) {}', options: { sourceType: 'module', next: true } },
    { code: 'async function f() { for (await using foo = bar;;) {} }', options: { next: true } },
    { code: 'async function f() { for await (using foo of bar) {} }', options: { next: true } },
    { code: 'async function f() { for await (await using foo of bar) {} }', options: { next: true } },
    { code: 'async function f() { for (await using of of bar) {} }', options: { next: true } },
    // contextual bindings
    { code: 'using of = null', options: { sourceType: 'module', next: true } },
    { code: 'using using = null', options: { sourceType: 'module', next: true } },
    { code: 'async function f() { await using using = null; }', options: { next: true } },
    { code: '{ using foo\n= null; }', options: { next: true } },
    { code: 'using /* comment */ foo = null', options: { sourceType: 'module', next: true } },
    { code: 'async function f() { await /* comment */ using foo = null; }', options: { next: true } },
    // 'using' as an identifier is still valid
    { code: 'using = null', options: { next: true } },
    { code: 'using.foo = null', options: { next: true } },
    { code: 'using[0] = null', options: { next: true } },
    { code: 'using(foo)', options: { next: true } },
    { code: 'using``', options: { next: true } },
    { code: 'using + foo', options: { next: true } },
    { code: 'using => using', options: { next: true } },
    { code: 'using: foo;', options: { next: true } },
    { code: 'using: for (using foo of bar) {}', options: { next: true } },
    { code: 'x = using', options: { next: true } },
    { code: 'function using() {}', options: { next: true } },
    { code: 'function f(using) {}', options: { next: true } },
    { code: 'let using = null', options: { next: true } },
    { code: 'const using = null', options: { next: true } },
    { code: 'var using = null', options: { next: true } },
    { code: 'class using {}', options: { next: true } },
    { code: 'import using from "foo"', options: { sourceType: 'module', next: true } },
    { code: 'new using()', options: { next: true } },
    { code: 'using\nfoo = null', options: { next: true } },
    { code: 'using\n[foo]', options: { next: true } },
    { code: 'using [foo] = bar', options: { next: true } },
    // 'using' as an identifier in for statement heads
    { code: 'for (using of bar) {}', options: { next: true } },
    { code: 'for (using of of) {}', options: { next: true } },
    { code: 'for (using[0] of bar) {}', options: { next: true } },
    { code: 'for (using.foo of bar) {}', options: { next: true } },
    { code: 'for (using = 0; using < 10; using++) {}', options: { next: true } },
    // escaped 'using' can only be an identifier
    { code: String.raw`\u0075sing = null`, options: { next: true } },
    { code: String.raw`\u0075sing.foo`, options: { next: true } },
    // 'await using' as an await expression on identifiers
    { code: 'async function f() { await using; }', options: { next: true } },
    { code: 'async function f() { await using.foo; }', options: { next: true } },
    { code: 'async function f() { await using[0]; }', options: { next: true } },
    { code: 'async function f() { await using\nfoo = null; }', options: { next: true } },
    // without the next option, 'using' is an identifier
    { code: 'using = null', options: {} },
    { code: 'using.foo = null', options: {} },
    { code: 'using: foo;', options: {} },
  ]);

  fail('Next - using declarations (fail)', [
    // 'using' is not allowed in the global scope of a script or commonjs
    { code: 'using foo = null', options: { next: true } },
    { code: 'using foo = null', options: { sourceType: 'commonjs', next: true } },
    { code: 'using foo = null', options: { sourceType: 'script', next: true } },
    { code: 'await using foo = null', options: { sourceType: 'commonjs', next: true } },
    // 'await using' outside async contexts. Note that the async context error
    // has priority over the script global scope error.
    { code: 'await using foo = null', options: { next: true } },
    { code: 'function f() { await using foo = null; }', options: { next: true } },
    { code: 'function f() { await using foo = null; }', options: { sourceType: 'module', next: true } },
    { code: 'for (await using foo of bar) {}', options: { next: true } },
    { code: 'function f() { for (await using foo of bar) {} }', options: { next: true } },
    // missing initializer
    { code: '{ using foo; }', options: { next: true } },
    { code: 'using foo', options: { sourceType: 'module', next: true } },
    { code: 'async function f() { await using foo; }', options: { next: true } },
    { code: 'for (using foo;;) {}', options: { next: true } },
    // using declarations are not allowed in for-in loop heads
    { code: 'for (using foo in bar) {}', options: { next: true } },
    { code: 'async function f() { for (await using foo in bar) {} }', options: { next: true } },
    // using declarations can not have destructuring patterns
    { code: 'using {foo} = bar', options: { sourceType: 'module', next: true } },
    { code: '{ using {foo} = bar; }', options: { next: true } },
    { code: 'async function f() { await using {foo} = bar; }', options: { next: true } },
    { code: 'for (using {foo} of bar) {}', options: { next: true } },
    { code: 'async function f() { for (await using {foo} of bar) {} }', options: { next: true } },
