/**
 * Parses an 'await using' declaration statement. The caller must have checked
 * the declaration head with `checkAwaitUsingDeclarationHead` first.
 *
 * @see [Link](https://tc39.es/proposal-explicit-resource-management)
 *
 * @param parser  Parser object
 * @param context Context masks
 * @param scope Scope object
 * @param origin Binding origin
 */
function parseAwaitUsingDeclaration(
  parser: Parser,
  context: Context,
  scope: Scope | undefined,
  privateScope: PrivateScope | undefined,
  origin: Origin,
): ESTree.VariableDeclaration {
  // AwaitUsingDeclaration ::
  //   'await' [no LineTerminator here] 'using' [no LineTerminator here] BindingList

  const start = parser.tokenStart;

  if ((context & Context.InAwaitContext) === 0 && !(context & Context.Module && context & Context.InGlobal)) {
    throw new ParseError(start, parser.currentLocation, Errors.AwaitUsingOutsideAsync);
  }

  nextToken(parser, context); // skips 'await'
  nextToken(parser, context); // skips 'using'

  const declarations = parseVariableDeclarationList(parser, context, scope, privateScope, BindingKind.AwaitUsing, origin);

